prompt --application/shared_components/security/authentications/tap_authentication
begin
wwv_flow_imp_shared.create_authentication(
 p_id=>wwv_flow_imp.id(5709401996355697047)
,p_name=>'TAP - Authentication'
,p_static_id=>'tap-authentication'
,p_scheme_type=>'NATIVE_CUSTOM'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'authentication_function', 'authenticate',
  'enable_legacy_attributes', 'N')).to_clob
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'FUNCTION authenticate (',
'  p_username VARCHAR2,',
'  p_password VARCHAR2',
') RETURN BOOLEAN',
'IS',
'  l_count NUMBER;',
'BEGIN',
'  IF p_username IS NULL OR p_password IS NULL THEN',
'    RETURN FALSE;',
'  END IF;',
'',
'  SELECT COUNT(*) INTO l_count',
'    FROM tms_employees',
'   WHERE UPPER(email) = UPPER(p_username)',
'     AND status = ''Active''',
'     AND password = hash_password(UPPER(p_username), p_password);',
'  RETURN l_count = 1;',
'END authenticate;'))
,p_use_secure_cookie_yn=>'N'
,p_ras_mode=>0
,p_version_scn=>'SH256:DMGis4h50_mICs1OkDbsC8NynRHevKvFGRji7lEH2wM'
,p_created_on=>wwv_flow_imp.dz('20261026094152Z')
,p_updated_on=>wwv_flow_imp.dz('20261026094152Z')
,p_created_by=>'GENDEV'
,p_updated_by=>'GENDEV'
);
end;
