'SELECT current_stage                          AS stage,',
'       Count(*)                               AS cnt,',
'       Round(Count(*) * 100.0 / Sum(Count(*))',
'                                  OVER (), 1) AS pct',
'FROM   tms_candidates',
'WHERE  applied_date BETWEEN Nvl(:P1_FROM_DATE, applied_date) AND',
'                            Nvl(:P1_TO_DATE, applied_date)',
'GROUP  BY current_stage',
'ORDER  BY Decode(current_stage, ''Applied'', 1,',
'                                ''Screening'', 2,',
'                                ''Interview'', 3,',
'                                ''Offer'', 4,',
'                                ''Hired'', 5,',
'                                6); '))
,p_series_type=>'funnel'
,p_items_value_column_name=>'CNT'
,p_items_label_column_name=>'STAGE'
,p_items_label_rendered=>true
,p_items_label_position=>'auto'
,p_threshold_display=>'onIndicator'
,p_link_target=>'f?p=&APP_ID.:4:&SESSION.::&DEBUG.::P4_STAGE:&STAGE.'
,p_link_target_type=>'REDIRECT_PAGE'
);
